"""Tests for card.py: size, a blank X title bar strip, and optical mark sizing."""

import os
import sys

from PIL import Image

sys.path.insert(0, os.path.dirname(__file__))
import brand  # noqa: E402
import card  # noqa: E402

COUNTS = {"skills": 107, "agents": 36, "hooks": 171}


def test_card_is_1200x630():
    out = card.render(Image.new("RGB", (2048, 1152), brand.BG), COUNTS)
    assert out.size == (brand.W, brand.H)


def test_bottom_strip_has_no_text_or_marks():
    out = card.render(Image.new("RGB", (2048, 1152), brand.BG), COUNTS)
    strip = out.crop((0, brand.SAFE_BOTTOM, brand.W, brand.H)).convert("L")
    assert strip.getextrema()[1] < 60


def test_blocky_marks_are_shrunk_relative_to_thin_ones():
    assert card.mark("opencode", 60).height < card.mark("claude", 60).height


def test_translucent_overlay_blends_instead_of_replacing():
    img = Image.new("RGBA", (10, 10), (0, 0, 0, 255))
    card.overlay(img, lambda o: o.rectangle([0, 0, 9, 9], fill=(255, 255, 255, 34)))
    px = img.getpixel((5, 5))
    assert isinstance(px, tuple)
    assert 20 < px[0] < 60 and px[3] == 255


def test_site_layout_carries_the_stat_words_and_one_number_colour(tmp_path, monkeypatch):
    import json

    monkeypatch.setattr(card, "SITE_ASSETS", str(tmp_path))
    card.write_site_assets(Image.new("RGB", (2048, 1152), brand.BG))
    layout = json.loads((tmp_path / "card-layout.json").read_text())
    assert layout["words"] == ["skills", "agents", "hooks"]
    assert set(layout["colors"]) == {"number", "word", "divider"}
    row = layout["statRow"]
    assert row["y"] + row["height"] < brand.SAFE_BOTTOM
